     <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Qualifying/raceid> "20"^^<http://www.w3.org/2001/XMLSchema#long> ;
     <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Qualifying/hasDrivers> ?d .
  ?d <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Driver/driverref> ?driverref .
  FILTER NOT EXISTS { ?q <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Qualifying/q2> ?q2 }
}

SELECT ?name WHERE {
  ?r a <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Race> ;
     <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Race/date> ?date ;
     <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Race/name> ?name .
  BIND(SUBSTR(STR(?date),1,7) AS ?ym)
  {
    SELECT (MIN(?ym2) AS ?minYm) WHERE {
      ?r2 a <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Race> ;
          <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Race/date> ?d2 .
      BIND(SUBSTR(STR(?d2),1,7) AS ?ym2)
    }
  }
  FILTER(?ym = ?minYm)
}

