  ?r1 a <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Result> ;
      <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Result/driverid> ?did ;
      <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Result/raceid> "853"^^<http://www.w3.org/2001/XMLSchema#long> ;
      <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Result/fastestlapspeed> ?s1 .

  ?r2 a <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Result> ;
      <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Result/driverid> ?did ;
      <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Result/raceid> "854"^^<http://www.w3.org/2001/XMLSchema#long> ;
      <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Result/fastestlapspeed> ?s2 .

  BIND(((xsd:decimal(?s1) - xsd:decimal(?s2)) / xsd:decimal(?s2)) * 100 AS ?percent)
}

