     <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Qualifying/raceid> "45" ;
     <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Qualifying/q3> "0:01:33" ;
     <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Qualifying/hasDrivers> ?d .
  ?d <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Driver/code> ?code .
