  ?d a <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Driver> ;
     <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Driver/nationality> "Japanese" ;
