     <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Driver/forename> ?forename ;
     <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Driver/surname> ?surname .
  BIND(SUBSTR(STR(?dob),1,4) AS ?birthYear)
  BIND((YEAR(NOW()) - xsd:integer(?birthYear)) AS ?age)
}
