  ?d a <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Driver> ;
     <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Driver/forename> "Alex" ;
     <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Driver/surname> "Yoong" ;
     <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Driver/driverid> ?did .
  ?res a <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Result> ;
       <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Result/driverid> ?did ;
       <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Result/raceid> ?rid .
  ?race a <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Race> ;
        <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Race/raceid> ?rid ;
        <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Race/circuitid> ?cid ;
        <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Race/name> ?name .
  FILTER(xsd:integer(?cid) < 20)
}

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT (xsd:decimal(?finished)/xsd:decimal(?total) AS ?completionRate)
WHERE {
  {
    SELECT (COUNT(?res) AS ?total) WHERE {
      ?res a <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Results> ;
           <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Results/hasRaces> ?race .
      ?race <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Race/date> "1983-07-16" .
    }
  }
  {
    SELECT (COUNT(?res2) AS ?finished) WHERE {
      ?res2 a <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Results> ;
            <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Results/hasRaces> ?race2 ;
