          <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/LapTime/raceid> ?raceId ;
          <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/LapTime/driverid> ?driverId ;
          <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/LapTime/lap> ?lap .
      ?r a <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Race> ;
         <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Race/raceid> ?raceId ;
         <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Race/year> ?year .
      FILTER(xsd:integer(?year) >= 2000 && xsd:integer(?year) <= 2005)
      ?d a <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Driver> ;
         <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Driver/driverid> ?driverId ;
         <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Driver/dob> ?dob .
      BIND(SUBSTR(STR(?dob),1,4) AS ?dobYear)
    }
  }
}

SELECT ?fullName
WHERE {
  ?lt a <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/LapTime> ;
      <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/LapTime/milliseconds> ?ms ;
      <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/LapTime/driverid> ?did .
  ?d a <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Driver> ;
     <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Driver/driverid> ?did ;
     <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Driver/forename> ?fn ;
     <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Driver/surname> ?sn .
  BIND(CONCAT(?fn, " ", ?sn) AS ?fullName)
}
ORDER BY ASC(xsd:integer(?ms))
LIMIT 20

SELECT ?url WHERE {
  ?c a <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Circuit> ;
     <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Circuit/country> "Italy" ;
     <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Circuit/url> ?url .
}

SELECT ?fullName ?nationality ?raceName WHERE {
  {
    SELECT (MAX(?dob) AS ?maxDob) WHERE {
      ?d a <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Driver> ;
         <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Driver/dob> ?dob .
    }
  }
  ?driver a <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Driver> ;
          <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Driver/dob> ?maxDob ;
          <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Driver/forename> ?fn ;
          <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Driver/surname> ?sn ;
          <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Driver/nationality> ?nationality ;
          <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Driver/driverid> ?driverId .
  BIND(CONCAT(?fn, " ", ?sn) AS ?fullName)

  ?res a <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Result> ;
       <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Result/driverid> ?driverId ;
       <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Result/raceid> ?rid .

  ?rc a <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Race> ;
      <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Race/raceid> ?rid ;
      <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Race/date> ?date ;
      <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Race/name> ?raceName .
}
ORDER BY ?date
LIMIT 1

SELECT ?fullName WHERE {
  ?c a <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Circuit> ;
     <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Circuit/name> "Marina Bay Street Circuit" ;
     <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Circuit/circuitid> ?cid .
  ?r a <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Race> ;
     <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Race/circuitid> ?cid ;
     <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Race/year> "2008" ;
     <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Race/round> "3" ;
     <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Race/raceid> ?rid .
  ?q a <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Qualifying> ;
     <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Qualifying/raceid> ?rid ;
     <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Qualifying/position> "1" ;
     <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Qualifying/driverid> ?did .
  ?d a <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Driver> ;
     <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Driver/driverid> ?did ;
     <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Driver/forename> ?forename ;
     <http://bird-bird_formula_1-ontology-20260809-235138/ontology/vkg-bird_formula_1/Driver/surname> ?surname .
  BIND(CONCAT(?forename, " ", ?surname) AS ?fullName)
}
